// Local compatibility repair for pi-subagents 0.56.0. Shared by every modern
// workflow in this parent process; held until authoritative completion, not receipt.
export class LaunchSemaphore {
	private active = 0;
	private readonly queue: Array<() => void> = [];

	constructor(readonly limit = 8) {
		if (!Number.isSafeInteger(limit) || limit < 1) throw new Error("Invalid child concurrency limit");
	}

	acquire(signal?: AbortSignal): Promise<() => void> {
		return new Promise((resolve, reject) => {
			const abort = () => {
				const index = this.queue.indexOf(grant);
				if (index >= 0) this.queue.splice(index, 1);
				reject(signal?.reason ?? new Error("Child launch cancelled"));
			};
			const grant = () => {
				signal?.removeEventListener("abort", abort);
				if (signal?.aborted) { abort(); return; }
				this.active++;
				let released = false;
				resolve(() => {
					if (released) return;
					released = true;
					this.active--;
					while (this.active < this.limit && this.queue.length) this.queue.shift()!();
				});
			};
			if (signal?.aborted) { abort(); return; }
			signal?.addEventListener("abort", abort, { once: true });
			if (this.active < this.limit) grant();
			else this.queue.push(grant);
		});
	}
}

// All workflow roots in this process import the same module. Child processes
// have no subagent authority (maxSubagentDepth=1) and cannot multiply this pool.
export const childLaunchSlots = new LaunchSemaphore(8);

